import React from "react";
import "./Preview.css";
import Navbar from "./Navbar";

function Preview({ data, updateData, onEdit, onConfirm }) {

  // ✅ HANDLE INLINE EDIT FOR LIMITS
  const handleLimitChange = (category, value) => {
    updateData(prev => ({
      ...prev,
      limits: {
        ...prev.limits,
        [category]: value
      }
    }));
  };

  return (
    <div className="preview-page">

      <Navbar title="Review Details" onBack={onEdit} />

      <div className="preview-wrapper">

        <h1 className="preview-title">Review Your Setup</h1>
        <p className="preview-subtitle">
          Please confirm your details before proceeding
        </p>

        <div className="preview-card">

          {/* INCOME */}
          <div className="preview-row">
            <div className="label">Income Type</div>
            <div className="value">{data.income}</div>
            <button onClick={onEdit}>Edit</button>
          </div>

          {/* CATEGORIES */}
          <div className="preview-row">
            <div className="label">Selected Categories</div>
            <div className="value">
              {data.categories?.length > 0
                ? data.categories.join(", ")
                : "None Selected"}
            </div>
          </div>

          {/* LIMITS WITH EDIT */}
          <div className="preview-row column">
            <div className="label">Budget Limits</div>

            {data.categories?.length > 0 ? (
              data.categories.map((cat) => (
                <div key={cat} className="limit-row">
                  <span>{cat}</span>

                  <input
                    type="number"
                    value={data.limits?.[cat] || ""}
                    onChange={(e) =>
                      handleLimitChange(cat, e.target.value)
                    }
                  />
                </div>
              ))
            ) : (
              <p>No categories selected</p>
            )}
          </div>

        </div>

        {/* ACTION BUTTONS */}
        <div className="preview-actions">
          <button className="secondary-btn" onClick={onEdit}>
            Edit Details
          </button>

          <button className="primary-btn" onClick={onConfirm}>
            Continue to Dashboard
          </button>
        </div>

      </div>
    </div>
  );
}

export default Preview;
